using FlexExtractor;
using System.Diagnostics;
static partial class Cases {
 public static void TestDestinationLeafJunctionRejectedExplicitly(){var root=Fresh();var c=Cfg(root);Source(c);Scan(c);var dest=Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Single();File.Delete(dest);var other=Path.Combine(root,"outside");Directory.CreateDirectory(other);using(var p=Process.Start(new ProcessStartInfo("cmd.exe"){UseShellExecute=false,RedirectStandardOutput=true,ArgumentList={"/c","mklink","/J",dest,other}})!){p.StandardOutput.ReadToEnd();p.WaitForExit();Program.Check(p.ExitCode==0,"leaf junction fixture failed");}var result=(ScanResult)Scan(c);Program.Check(result.Failed>0&&result.Messages.Any(x=>x.Contains("重解析")),"leaf junction was not explicitly rejected");}
 public static void TestJunctionDestinationRejected(){var root=Fresh();var c=Cfg(root);Source(c);var other=Path.Combine(root,"outside");Directory.CreateDirectory(other);var p=new ProcessStartInfo("cmd.exe"){UseShellExecute=false,RedirectStandardOutput=true};p.ArgumentList.Add("/c");p.ArgumentList.Add("mklink");p.ArgumentList.Add("/J");p.ArgumentList.Add(c.DispenseItems[0].SaveFolder);p.ArgumentList.Add(other);using(var proc=Process.Start(p)!){var output=proc.StandardOutput.ReadToEnd();proc.WaitForExit();Program.Check(proc.ExitCode==0,"junction fixture failed "+output);} Rejected(()=>Scan(c));Program.Check(Directory.GetFiles(other).Length==0,"junction followed");}
}
